# Local R statistical engine. Data and options enter as JSON, never as executable code.
gm_run <- function(packet) {
 accent<-if(!is.null(packet$color)&&grepl('^#[0-9A-Fa-f]{6}$',packet$color))packet$color else '#2E7D58'
 id<-packet$id;o<-packet$options;f<-packet$fields;alpha<-packet$alpha;level<-1-alpha
 opt<-function(k,default=NULL){x<-o[[k]];if(is.null(x)||identical(x,''))default else x}
 num<-function(k,default=0,min=-Inf,max=Inf,integer=FALSE){x<-suppressWarnings(as.numeric(opt(k,default)));need(length(x)==1&&is.finite(x),paste0('Enter a number for "',k,'".'));need(x>=min,paste0('"',k,'" must be at least ',min,'.'));need(x<=max,paste0('"',k,'" must be at most ',max,'.'));if(integer)need(x==floor(x),paste0('"',k,'" must be a whole number.'));x}
 need<-function(ok,message){if(!isTRUE(ok))stop(message,call.=FALSE)}
 fields<-function(k)unlist(f[[k]],use.names=FALSE)
 decode<-function(cols){if(!length(cols))return(data.frame());a<-lapply(cols,function(c)vapply(c$values,function(v)if(is.null(v))if(c$type=='numeric')NA_real_ else NA_character_ else if(c$type=='numeric')as.numeric(v)else as.character(v),if(c$type=='numeric')numeric(1)else character(1)));d<-as.data.frame(a,stringsAsFactors=FALSE);for(k in names(cols))if(cols[[k]]$type=='categorical')d[[k]]<-factor(d[[k]]);d}
 d<-decode(packet$data);originalN<-nrow(d);used<-originalN;tables<-list();plots<-list();notes<-character();diagnostics<-character();warnings<-character();model<-NULL;outputData<-NULL;future<-NULL
 y<-fields('y');x<-fields('predictors');g<-fields('group');subject<-fields('subject');time<-fields('time');variables<-fields('variables')
 value<-function(k){v<-fields(k);if(length(v))d[[v[1]]]else NULL}
 add<-function(z,title='Results',rn=FALSE){if(is.null(z))return();if(is.matrix(z))z<-unclass(z);if(is.atomic(z)&&is.null(dim(z)))z<-data.frame(Value=z);z<-as.data.frame(z,stringsAsFactors=FALSE);if(rn)z<-cbind(Term=rownames(z),z,row.names=NULL);tables[[length(tables)+1]]<<-list(title=title,columns=names(z),rows=unname(lapply(seq_len(min(5000,nrow(z))),function(i)unname(as.list(z[i,,drop=FALSE])))),totalRows=nrow(z))}
 diagnostic<-function(z)diagnostics<<-c(diagnostics,capture.output(z))
 draw<-function(title,fun){file<-tempfile(fileext='.svg');grDevices::svg(file,width=9,height=5.5,bg='#FFFEFA',family='sans');par(col='#20362F',col.axis='#20362F',col.lab='#20362F',col.main='#194F39',las=1,mar=c(4.5,4.8,3,1));tryCatch(fun(),error=function(e){plot.new();text(.5,.5,conditionMessage(e),cex=.7)});dev.off();plots[[length(plots)+1]]<<-list(title=title,svg=paste(readLines(file,warn=FALSE),collapse='\n'));unlink(file)}
 clean<-function(v=unique(unlist(f,use.names=FALSE))){v<-intersect(v,names(d));if(length(v))d<<-droplevels(d[complete.cases(d[,v,drop=FALSE]),,drop=FALSE]);used<<-nrow(d);need(used>0,'No complete observations for the selected variables.')}
 group<-function(v,k=NULL){v<-droplevels(factor(v));need(nlevels(v)>=2,'At least two observed groups are required.');if(!is.null(k))need(nlevels(v)==k,paste('Exactly',k,'groups are required.'));v}
 numbers<-function(s){v<-suppressWarnings(as.numeric(strsplit(s,'[,;[:space:]]+')[[1]]));need(length(v)>0&&all(is.finite(v)),'Enter finite comma-separated numbers.');v}
 countTable<-function(s){need(nzchar(s),'Enter a count table, one comma-separated row per line.');a<-lapply(strsplit(s,'\n')[[1]],numbers);need(length(unique(lengths(a)))==1,'All table rows need the same number of cells.');z<-do.call(rbind,a);need(all(z>=0&z==floor(z))&&sum(z)>0,'Counts must be nonnegative integers with a positive total.');z}
 rhs<-function(v){need(length(v)>0,'Select predictors.');paste(v,collapse='+')}
 formula<-function(v=x)as.formula(paste(y,'~',rhs(v)))
 test<-function(h){if(inherits(h,'htest')){add(data.frame(Statistic=if(length(h$statistic))as.numeric(h$statistic)[1]else NA,DF=if(length(h$parameter))paste(h$parameter,collapse=', ')else'',P=h$p.value,Method=h$method),'Test');if(length(h$estimate))add(data.frame(Estimate=names(h$estimate),Value=as.numeric(h$estimate)),'Estimates');if(length(h$conf.int))add(data.frame(Lower=h$conf.int[1],Upper=h$conf.int[2],Confidence=attr(h$conf.int,'conf.level')),'Confidence interval');notes<<-c(notes,h$alternative)}else diagnostic(h)}
 fitout<-function(m){model<<-m;used<<-if(inherits(m,'coxph'))m$n else tryCatch(as.numeric(nobs(m)),error=function(e)used);if(length(used)!=1||!is.finite(used))used<<-nrow(d);diagnostic(summary(m));
  if(is.list(m)&&isFALSE(m$converged))stop('The model did not converge. Estimates are not released.',call.=FALSE)
  if(inherits(m,'merMod')){msg<-m@optinfo$conv$lme4$messages;need(!length(msg)||all(grepl('singular',msg)),'The mixed model did not converge.');add(as.data.frame(lme4::VarCorr(m)),'Random-effect variances');notes<<-c(notes,paste('Singular fit:',lme4::isSingular(m)))}
  s<-summary(m);co<-if(inherits(m,'rq')||inherits(m,'multinom')||inherits(m,'plm')||inherits(m,'pgmm'))NULL else if(inherits(m,'gam'))s$p.table else tryCatch(coef(s),error=function(e)NULL);if(inherits(m,'coxph')&&is.matrix(co))co<-co[,c(1,3,4,5),drop=FALSE];if(is.matrix(co)){need(ncol(co)>=2&&all(is.finite(co[,1:2]))&&all(co[,2]>0),'Coefficient estimates or standard errors are not finite/positive. Review model identification and convergence.');z<-data.frame(Term=rownames(co),co,check.names=FALSE,row.names=NULL);z<-z[order(z$Term=='(Intercept)'),,drop=FALSE];if(ncol(co)>=2&&all(is.finite(co[,1:2]))){crit<-if((inherits(m,'lm')||inherits(m,'plm'))&&!inherits(m,'glm')&&!inherits(m,'rlm'))qt(1-alpha/2,df.residual(m))else qnorm(1-alpha/2);z[['Lower CI']]<-z[[2]]-crit*z[[3]];z[['Upper CI']]<-z[[2]]+crit*z[[3]]};add(z,'Coefficients')}
  ll<-tryCatch(as.numeric(logLik(m)),error=function(e)NA_real_);aa<-tryCatch(as.numeric(AIC(m)),error=function(e)NA_real_);bb<-tryCatch(as.numeric(BIC(m)),error=function(e)NA_real_);add(data.frame(Statistic=c('Number of observations','Log likelihood','AIC','BIC'),Value=c(used,ll,aa,bb)),'Model summary')
  if(inherits(m,'lm')&&!inherits(m,'glm')&&!inherits(m,'rlm')){need(!anyNA(coef(m)),'The model is rank deficient. Remove redundant predictors or empty interaction cells.');add(anova(m),'Analysis of variance',TRUE);draw('Residuals versus fitted',function(){plot(fitted(m),residuals(m),pch=16,col=adjustcolor(accent,alpha.f=.45),xlab='Fitted',ylab='Residual');abline(h=0,lty=2)});draw('Residual Q–Q plot',function(){qqnorm(residuals(m),pch=16,col=accent);qqline(residuals(m))});diagnostics<<-c(diagnostics,tryCatch(capture.output(lmtest::bptest(m)),error=function(e)conditionMessage(e)),tryCatch(capture.output(car::vif(m)),error=function(e)conditionMessage(e)))}
  if(inherits(m,'glm')&&family(m)$family=='binomial'){yy<-model.response(model.frame(m));if(is.factor(yy))yy<-as.integer(yy)-1;need(!all((predict(m,type='link')>0)==yy),'Perfect classification detected. Check separation before interpreting this binary model.')}
  pp<-tryCatch({if(inherits(m,'lm')&&!inherits(m,'glm')&&!inherits(m,'rlm'))predict(m,newdata=future,interval='prediction',level=level)else predict(m,newdata=future,type='response')},error=function(e)NULL);if(!is.null(pp))add(head(if(is.null(dim(pp)))data.frame(Prediction=as.numeric(pp))else pp,200),if(is.null(future))'Predictions: first 200 analysis rows'else'Predictions for supplied data')
 }
 run<-function(){
 set.seed(num('seed',1729,min=0,integer=TRUE))
 if(grepl('^summary_t',id)){if(id=='summary_tp'){m<-num('meanDifference');sd<-num('sdDifference',min=0);n<-num('pairs',min=2,integer=TRUE);se<-sd/sqrt(n);df<-n-1;est<-m-num('null');used<<-n}else{m1<-num('mean1');s1<-num('sd1',min=0);n1<-num('n1',min=2,integer=TRUE);if(id=='summary_t1'){est<-m1-num('null');se<-s1/sqrt(n1);df<-n1-1;used<<-n1}else{m2<-num('mean2');s2<-num('sd2',min=0);n2<-num('n2',min=2,integer=TRUE);v1<-s1*s1/n1;v2<-s2*s2/n2;est<-m1-m2;se<-sqrt(v1+v2);df<-(v1+v2)^2/(v1*v1/(n1-1)+v2*v2/(n2-1));used<<-n1+n2}};need(se>0,'The summaries imply zero standard error.');add(data.frame(Estimate=est,SE=se,t=est/se,DF=df,P=2*pt(-abs(est/se),df),Lower=est-qt(1-alpha/2,df)*se,Upper=est+qt(1-alpha/2,df)*se));return()}
 if(id%in%c('prop1','prop2','binomial')){if(opt('inputMode','raw')=='summary'){sx<-if(id=='prop2')c(num('successes1',min=0,integer=TRUE),num('successes2',min=0,integer=TRUE))else num('successes',min=0,integer=TRUE);ns<-if(id=='prop2')c(num('trials1',min=1,integer=TRUE),num('trials2',min=1,integer=TRUE))else num('trials',min=1,integer=TRUE)}else{clean();yy<-value('y');need(all(yy%in%c(0,1)),'Outcome must be coded 0/1.');if(id=='prop2'){gg<-group(value('group'),2);sx<-as.numeric(tapply(yy,gg,sum));ns<-as.numeric(table(gg));notes<<-c(notes,paste('First minus second:',paste(levels(gg),collapse=' minus ')))}else{sx<-sum(yy);ns<-length(yy)}};need(all(sx<=ns),'Successes cannot exceed trials.');used<<-sum(ns);test(if(id=='binomial')binom.test(sx,ns,p=num('null',.5,min=0,max=1),conf.level=level)else prop.test(sx,ns,p=if(id=='prop2')NULL else num('null',.5,min=0,max=1),correct=FALSE,conf.level=level));add(data.frame(Group=seq_along(sx),Successes=sx,Trials=ns,Proportion=sx/ns),'Sample proportions');return()}
 if(id%in%c('gof','fisher','mcnemar','mcnemar_exact')){if(opt('inputMode','raw')=='summary')z<-if(id=='gof')numbers(opt('counts',''))else countTable(opt('table',''))else{clean();if(id=='gof')z<-table(value('group'))else if(id=='fisher')z<-table(value('group'),value('group2'))else{need(all(value('y')%in%c(0,1))&&all(value('y2')%in%c(0,1)),'Paired outcomes must be coded 0/1.');z<-table(factor(value('y'),levels=0:1),factor(value('y2'),levels=0:1))}};used<<-sum(z);if(id=='gof'){p<-opt('expected','');p<-if(nzchar(p))numbers(p)else rep(1/length(z),length(z));need(all(z>=0&z==floor(z))&&sum(z)>0,'Observed counts must be nonnegative integers with a positive total.');need(length(p)==length(z)&&all(p>0)&&abs(sum(p)-1)<1e-7,'Expected probabilities must match categories and sum to one.');h<-chisq.test(z,p=p);add(data.frame(Observed=as.numeric(z),Expected=as.numeric(h$expected)),'Counts')}else if(id=='fisher')h<-fisher.test(z,conf.level=level)else{need(identical(dim(z),c(2L,2L)),'A 2×2 paired count table is required.');need(z[1,2]+z[2,1]>0,'There are no discordant pairs.');h<-if(id=='mcnemar_exact')binom.test(z[1,2],z[1,2]+z[2,1],p=.5,conf.level=level)else mcnemar.test(z)};test(h);if(id!='gof')add(z,'Count table',TRUE);return()}
 if(id%in%c('mannwhitney','signedrank','kruskal','friedman','permutation')){clean();yy<-value('y');if(id=='mannwhitney'){gg<-group(value('group'),2);h<-wilcox.test(yy~gg,exact=FALSE,conf.int=TRUE,conf.level=level);test(h);add(data.frame(Rank.biserial=2*as.numeric(h$statistic)/prod(table(gg))-1),'Effect size');notes<<-c(notes,'Rank-sum inference concerns distribution/location. A median interpretation requires additional shape assumptions.')}else if(id=='signedrank'){need(any(yy!=value('y2')),'All paired differences are zero.');test(wilcox.test(yy,value('y2'),paired=TRUE,exact=FALSE,conf.int=TRUE,conf.level=level))}else if(id=='kruskal'){gg<-group(value('group'));test(kruskal.test(yy,gg));rr<-rank(yy);add(data.frame(Group=levels(gg),N=as.integer(table(gg)),Median=as.numeric(tapply(yy,gg,median)),Mean.rank=as.numeric(tapply(rr,gg,mean)),Rank.sum=as.numeric(tapply(rr,gg,sum))),'Group summaries')}else if(id=='friedman'){gg<-group(value('group'));ss<-factor(value('subject'));need(all(table(ss,gg)==1),'Exactly one complete observation per subject × condition is required.');test(friedman.test(yy,gg,ss))}else{dd<-data.frame(y=yy,g=group(value('group'),2));ff<-y~g;if(length(fields('strata'))){dd$s<-factor(value('strata'));ff<-y~g|s};set.seed(num('seed',1729,min=0,integer=TRUE));h<-coin::independence_test(ff,data=dd,distribution=coin::approximate(nresample=num('repetitions',9999,min=99,max=100000,integer=TRUE)));add(data.frame(Statistic=as.numeric(coin::statistic(h)),P=as.numeric(coin::pvalue(h))));notes<<-c(notes,'Permutation inference requires exchangeability within the specified design/strata.')};return()}
 if(id%in%c('welch_anova','factorial','ancova','repeated','tukey','gameshowell','dunnett','contrasts','pairwise')){clean();yy<-value('y');if(id%in%c('factorial','ancova')){vv<-if(id=='factorial')fields('factors')else c(g,fields('covariates'));for(k in if(id=='factorial')fields('factors')else g)d[[k]]<-group(d[[k]]);if(opt('ss','II')=='III')for(k in vv)if(is.factor(d[[k]]))contrasts(d[[k]])<-contr.sum(nlevels(d[[k]]));ff<-as.formula(paste(y,'~',paste(vv,collapse=if(isTRUE(opt('interactions',id=='factorial')))'*'else'+')));m<-lm(ff,data=d);fitout(m);add(car::Anova(m,type=opt('ss','II')),'Joint effect tests',TRUE);return()};gg<-group(value('group'));ss<-value('subject');if(id=='repeated'){ss<-factor(ss);need(all(table(ss,gg)==1),'Repeated ANOVA requires a complete unique subject × condition design.');mat<-as.matrix(reshape(data.frame(s=ss,g=gg,y=yy),idvar='s',timevar='g',direction='wide')[,-1,drop=FALSE]);m<-lm(mat~1);a<-car::Anova(m,idata=data.frame(condition=factor(seq_len(ncol(mat)))),idesign=~condition,type='III');diagnostic(summary(a,multivariate=FALSE));add(data.frame(Subjects=nrow(mat),Conditions=ncol(mat)),'Design');notes<<-c(notes,'Diagnostics include sphericity and Greenhouse–Geisser/Huynh–Feldt corrections.');used<<-nrow(mat);return()};need(all(table(gg)>=2),'Every group needs at least two observations.');dd<-data.frame(y=yy,g=gg);if(id=='welch_anova'){test(oneway.test(y~g,data=dd,var.equal=FALSE));return()};m<-aov(y~g,dd);if(id=='tukey')add(TukeyHSD(m,conf.level=level)$g,'Tukey simultaneous comparisons',TRUE);if(id=='gameshowell'){lv<-levels(gg);k<-length(lv);rr<-list();for(i in seq_len(k-1))for(j in (i+1):k){a<-yy[gg==lv[i]];b<-yy[gg==lv[j]];v1<-var(a)/length(a);v2<-var(b)/length(b);need(v1+v2>0,'A comparison has zero sampling variance.');se<-sqrt((v1+v2)/2);df<-(v1+v2)^2/(v1^2/(length(a)-1)+v2^2/(length(b)-1));dif<-mean(a)-mean(b);q<-abs(dif)/se;crit<-qtukey(level,k,df);rr[[length(rr)+1]]<-data.frame(Contrast=paste(lv[i],'-',lv[j]),Difference=dif,DF=df,P.adjusted=ptukey(q,k,df,lower.tail=FALSE),Lower=dif-crit*se,Upper=dif+crit*se)};add(do.call(rbind,rr),'Games–Howell simultaneous comparisons')};if(id=='dunnett'){ref<-opt('reference',levels(gg)[1]);need(ref%in%levels(gg),'The control label is not an observed group.');dd$g<-relevel(gg,ref);m<-aov(y~g,dd);z<-multcomp::glht(m,linfct=multcomp::mcp(g='Dunnett'));diagnostic(summary(z));add(confint(z,level=level)$confint,'Dunnett simultaneous intervals',TRUE)};if(id=='contrasts'){C<-do.call(rbind,lapply(strsplit(opt('contrasts',''),'\n')[[1]],numbers));need(ncol(C)==nlevels(gg)&&all(abs(rowSums(C))<1e-8),'Contrast rows need one coefficient per displayed group and must sum to zero.');m<-lm(y~0+g,dd);z<-multcomp::glht(m,linfct=C);s<-summary(z,test=multcomp::adjusted(opt('adjust','holm')));add(data.frame(Estimate=coef(z),SE=sqrt(base::diag(vcov(z))),P.adjusted=as.numeric(s$test$pvalues)),'Planned contrasts');diagnostic(s)};if(id=='pairwise'){z<-if(isTRUE(opt('rank',FALSE)))pairwise.wilcox.test(yy,gg,p.adjust.method=opt('adjust','holm'),exact=FALSE)else pairwise.t.test(yy,gg,p.adjust.method=opt('adjust','holm'),pool.sd=FALSE);add(z$p.value,'Adjusted pairwise p-values',TRUE)};add(data.frame(Group=levels(gg),N=as.integer(table(gg)),Mean=as.numeric(tapply(yy,gg,mean)),SD=as.numeric(tapply(yy,gg,sd))),'Group summaries');return()}
 if(id%in%c('multinomial','probit','negbin','hurdle','zeroinfl','robustreg','quantile','spline','gam','mixed','glmm','panel_fe','panel_re','panel_dynamic')){clean();ff<-formula();if(length(fields('offset'))){ee<-value('offset');need(all(ee>0),'Exposure must be positive.');d$.exposure<-log(ee);ff<-update(ff,.~.+offset(.exposure))};if(id%in%c('negbin','hurdle','zeroinfl'))need(is.numeric(value('y'))&&all(value('y')>=0&value('y')==floor(value('y'))),'Count outcomes must be nonnegative integers.');m<-switch(id,probit=glm(ff,data=d,family=binomial(link='probit')),negbin=MASS::glm.nb(ff,data=d),hurdle=pscl::hurdle(ff,data=d,dist=opt('countFamily','negbin')),zeroinfl=pscl::zeroinfl(ff,data=d,dist=opt('countFamily','negbin')),robustreg=MASS::rlm(ff,data=d,maxit=200),quantile=quantreg::rq(ff,data=d,tau=num('tau',.5,min=.001,max=.999)),NULL)
  if(id=='multinomial'){d[[y]]<-group(value('y'));need(nlevels(d[[y]])>=3,'Select an outcome with at least three categories.');m<-nnet::multinom(ff,data=d,trace=FALSE,maxit=1000,Hess=TRUE);need(m$convergence==0,'Multinomial regression did not converge.');s<-summary(m);b<-s$coefficients;se<-s$standard.errors;need(all(is.finite(b))&&all(is.finite(se)&se>0),'Multinomial coefficients or standard errors are not estimable.');add(do.call(rbind,lapply(seq_len(nrow(b)),function(i)data.frame(Outcome=rownames(b)[i],Term=colnames(b),Estimate=b[i,],SE=se[i,],Z=b[i,]/se[i,],P=2*pnorm(-abs(b[i,]/se[i,])),Lower=b[i,]-qnorm(1-alpha/2)*se[i,],Upper=b[i,]+qnorm(1-alpha/2)*se[i,]))),'Multinomial coefficients');notes<<-c(notes,paste('Reference outcome:',levels(d[[y]])[1]))}
  if(id%in%c('spline','gam')){k<-num('df',if(id=='spline')4 else 5,min=2,max=30,integer=TRUE);terms<-vapply(x,function(v)if(is.numeric(d[[v]]))if(id=='spline')paste0('splines::ns(',v,',df=',k,')')else paste0('s(',v,',k=',min(k,length(unique(d[[v]]))-1),')')else v,character(1));ff<-as.formula(paste(y,'~',paste(terms,collapse='+')));if(id=='spline')m<-lm(ff,data=d)else{fa<-switch(opt('family','gaussian'),gaussian=gaussian(),binomial=binomial(),poisson=poisson(),negbin=mgcv::nb());m<-mgcv::gam(ff,data=d,family=fa,method='REML');s<-summary(m);if(!is.null(s$s.table))add(s$s.table,'Smooth terms',TRUE);draw('Smooth effects',function()plot(m,pages=1,shade=TRUE,shade.col='#D6E8DD'));diagnostic(mgcv::k.check(m))}}
  if(id%in%c('mixed','glmm')){need(length(subject)==1,'Choose a grouping identifier.');d[[subject]]<-group(value('subject'));slope<-opt('randomSlope','');need(!nzchar(slope)||slope%in%x,'Random slope must be a selected predictor.');ff<-as.formula(paste(y,'~',rhs(x),'+(1',if(nzchar(slope))paste('+',slope)else'', '|',subject,')'));m<-if(id=='mixed')lme4::lmer(ff,data=d,REML=isTRUE(opt('reml',TRUE)))else if(opt('family','binomial')=='negbin')lme4::glmer.nb(ff,data=d)else lme4::glmer(ff,data=d,family=switch(opt('family','binomial'),binomial=binomial(),poisson=poisson()));notes<<-c(notes,'Mixed-model fixed-effect intervals are asymptotic Wald intervals. Linear mixed-model t statistics have no automatically assigned finite-sample p-values.');if(id=='mixed'&&!nzchar(slope)){vv<-as.data.frame(lme4::VarCorr(m));add(data.frame(ICC=vv$vcov[1]/sum(vv$vcov)),'Intraclass correlation')}}
  if(id%in%c('panel_fe','panel_re','panel_dynamic')){suppressPackageStartupMessages(library(plm));need(!anyDuplicated(d[,c(subject,time)]),'Panel identifier × time must be unique.');pd<-plm::pdata.frame(d,index=c(subject,time));if(id=='panel_dynamic'){L<-num('lags',2,min=2,max=10,integer=TRUE);ff<-as.formula(paste(y,'~lag(',y,',1)+',rhs(x),'|lag(',y,',2:',L,')'));m<-plm::pgmm(ff,data=pd,effect='individual',model='twosteps',transformation='d',collapse=TRUE);diagnostic(summary(m,robust=TRUE));add(summary(m,robust=TRUE)$coefficients,'Difference-GMM coefficients',TRUE)}else{m<-plm::plm(ff,data=pd,model=if(id=='panel_fe')'within'else'random',effect=opt('effects','individual'));cdf<-length(unique(d[[subject]]))-1;cc<-lmtest::coeftest(m,vcov.=plm::vcovHC(m,type='HC1',cluster='group'),df=cdf);add(cbind(unclass(cc),Lower=cc[,1]-qt(1-alpha/2,cdf)*cc[,2],Upper=cc[,1]+qt(1-alpha/2,cdf)*cc[,2]),'Panel-clustered inference',TRUE);notes<<-c(notes,paste('Inference clusters by panel and uses',cdf,'degrees of freedom. Conventional fit details appear in Diagnostics.'))}}
  if(id%in%c('hurdle','zeroinfl'))for(k in names(summary(m)$coefficients)){cc<-summary(m)$coefficients[[k]];need(all(is.finite(cc[,1:2]))&&all(cc[,2]>0),'A count/zero component is not identified.');add(cc,paste(k,'component'),TRUE)}
  if(id=='quantile'){add(summary(m,se='nid')$coefficients,'Quantile coefficients',TRUE);notes<<-c(notes,'Quantile inference uses the nid sparsity estimator.')}
