  if(id=='ardl'){L<-num('lags',2,min=1,max=12,integer=TRUE);tsd<-ts(d[,c(y,x),drop=FALSE],frequency=freq);m<-ARDL::ardl(formula(),data=tsd,order=rep(L,length(x)+1));fitout(m);notes<<-c(notes,'Distributed-lag estimates do not establish cointegration. Check integration orders before interpreting a long-run relationship.');return()}
  if(id%in%c('var','vecm')){need(length(variables)>=2,'Select at least two series.');zz<-as.matrix(d[,variables,drop=FALSE]);L<-num('lags',2,min=1,max=12,integer=TRUE);if(id=='var'){m<-vars::VAR(zz,p=L,type='const');diagnostic(summary(m));for(k in names(m$varresult))add(coef(summary(m$varresult[[k]])),paste('Equation',k),TRUE);diagnostic(vars::serial.test(m));diagnostic(vars::stability(m))}else{need(L>=2,'Johansen/VECM requires at least two level lags.');r<-num('rank',1,min=1,max=ncol(zz)-1,integer=TRUE);jo<-urca::ca.jo(zz,type='trace',ecdet='const',K=L);diagnostic(summary(jo));m<-vars::vec2var(jo,r=r);add(jo@V,'Cointegrating vectors',TRUE);notes<<-c(notes,'The chosen cointegration rank is user-specified. Johansen trace statistics and critical values appear in Diagnostics.')};pr<-predict(m,n.ahead=h,ci=level);for(k in names(pr$fcst))add(cbind(Horizon=seq_len(h),pr$fcst[[k]]),paste('Forecast',k));draw('Multivariate forecasts',function()plot(pr));return()}
  if(id=='breaks'){ff<-if(length(x))formula()else as.formula(paste(y,'~1'));b<-strucchange::breakpoints(ff,data=d,h=num('trim',.15,min=.05,max=.45));k<-num('breaks',1,min=1,max=10,integer=TRUE);br<-strucchange::breakpoints(b,breaks=k);need(all(is.finite(br$breakpoints)),'The requested break count cannot be estimated with this sample and trimming.');add(data.frame(Row=br$breakpoints,Time=tt[br$breakpoints]),'Estimated breaks');diagnostic(summary(b));diagnostic(confint(b,breaks=k));test(strucchange::sctest(strucchange::Fstats(ff,data=d,from=num('trim',.15)),type='supF'));draw('Break selection by BIC',function()plot(b));return()}
  if(id=='countts'){yy<-value('y');need(all(yy>=0&yy==floor(yy)),'Count outcome must be nonnegative integers.');L<-num('lags',1,min=1,max=12,integer=TRUE);need(length(yy)>L+10,'Insufficient time points.');for(j in seq_len(L))d[[paste0('lag',j)]]<<-c(rep(NA,j),log1p(head(yy,-j)));ff<-as.formula(paste(y,'~',paste(c(x,paste0('lag',seq_len(L))),collapse='+')));m<-if(opt('family','negbin')=='poisson')glm(ff,data=d,family=poisson())else MASS::glm.nb(ff,data=d);fitout(m);draw('Count-model residual autocorrelation',function()acf(residuals(m,type='pearson')));notes<<-c(notes,'Conditional count regression uses log(1 + lagged counts). This is not an INAR or INGARCH estimator.');return()}
 }
 if(id%in%c('merge','append','long','wide','duplicates')){keys<-fields('keys');if(id=='duplicates'){need(length(keys)>0,'Choose key columns.');dup<-duplicated(d[,keys,drop=FALSE])|duplicated(d[,keys,drop=FALSE],fromLast=TRUE);add(cbind(Source.row=which(dup),d[dup,,drop=FALSE]),'Duplicate keys');notes<<-c(notes,paste(sum(dup),'rows belong to duplicated keys.'));return()};if(id%in%c('merge','append')){other<-decode(packet$other);need(nrow(other)>0,'Load a second dataset for preview.');if(id=='append'){need(setequal(names(d),names(other)),'Append requires matching columns.');need(all(vapply(names(d),function(k)is.numeric(d[[k]])==is.numeric(other[[k]]),logical(1))),'Append column types must match.');for(k in names(d))if(is.factor(d[[k]])){d[[k]]<-as.character(d[[k]]);other[[k]]<-as.character(other[[k]])};outputData<<-rbind(d,other[,names(d),drop=FALSE])}else{need(length(keys)>0&&all(keys%in%names(other)),'Both datasets must contain the selected keys.');need(!anyNA(d[,keys,drop=FALSE])&&!anyNA(other[,keys,drop=FALSE]),'Merge keys must be nonmissing.');need(isTRUE(opt('manyToMany',FALSE))||!(anyDuplicated(d[,keys,drop=FALSE])&&anyDuplicated(other[,keys,drop=FALSE])),'Both inputs have duplicate keys. Explicitly enable many-to-many merging after inspecting duplicates.');join<-opt('join','left');need(join%in%c('left','right','inner','full'),'Unknown join.');outputData<<-merge(d,other,by=keys,all.x=join%in%c('left','full'),all.y=join%in%c('right','full'),sort=FALSE)}}else if(id=='long'){need(!anyDuplicated(d[[subject]]),'Long reshape requires unique subject IDs in wide data.');outputData<<-reshape(d,idvar=subject,varying=variables,v.names='value',timevar='measurement',times=vapply(variables,function(v)packet$data[[v]]$name,character(1)),direction='long')}else{need(!anyDuplicated(d[,c(subject,time)]),'Wide reshape requires unique subject × time.');outputData<<-reshape(d[,c(subject,time,y),drop=FALSE],idvar=subject,timevar=time,direction='wide')};add(head(outputData,200),'Data preview: first 200 rows');add(data.frame(Input.rows=nrow(d),Output.rows=nrow(outputData),Output.columns=ncol(outputData)),'Data operation summary');notes<<-c(notes,'Preview the output before replacing the active dataset.');return()}
 stop(paste('Unsupported analysis:',id),call.=FALSE)
 }
 error<-NULL
 tryCatch(withCallingHandlers(run(),warning=function(w){warnings<<-c(warnings,conditionMessage(w));invokeRestart('muffleWarning')}),error=function(e){error<<-conditionMessage(e)})
 if(!is.null(error)){tables<-list();plots<-list();outputData<-NULL}
 # Put sample and fit information ahead of coefficient tables, following existing output order.
 if(length(tables)){idx<-order(vapply(tables,function(t)if(t$title=='Model summary')0 else if(grepl('Coefficients|coefficients',t$title))2 else 1,numeric(1)));tables<-tables[idx]}
 allColumns<-c(packet$data,packet$other[setdiff(names(packet$other),names(packet$data))]);labels<-vapply(allColumns,function(c)c$name,character(1))
 list(id=id,error=error,inputN=originalN,analysisN=used,excludedN=if(id=='repeated')originalN-nrow(d)else max(0,originalN-used),tables=tables,plots=plots,diagnostics=diagnostics,notes=unique(notes),warnings=unique(warnings),labels=as.list(labels),outputData=if(is.null(outputData))NULL else list(names=names(outputData),rows=unname(lapply(seq_len(nrow(outputData)),function(i)unname(as.list(outputData[i,,drop=FALSE]))))),runtime=R.version.string,packages=as.list(vapply(loadedNamespaces(),function(p)as.character(utils::packageVersion(p)),character(1))))
